import { useState } from 'react';
import API from '../api/axios';

export default function PostCard({ post, onUpdate }) {
  const [comment, setComment] = useState('');
  const username = localStorage.getItem('username');
  const liked = post.likes.includes(username);

  const handleLike = async () => {
    await API.put(`/posts/${post._id}/like`);
    onUpdate();
  };

  const handleComment = async e => {
    e.preventDefault();
    if (!comment) return;
    await API.post(`/posts/${post._id}/comment`, { text: comment });
    setComment('');
    onUpdate();
  };

  return (
    <div style={styles.card}>
      <div style={styles.header}>
        <span style={styles.avatar}>👤</span>
        <div>
          <p style={styles.username}>{post.username}</p>
          <p style={styles.time}>
            {new Date(post.createdAt).toLocaleString()}
          </p>
        </div>
      </div>

      {post.text && <p style={styles.text}>{post.text}</p>}

      {post.image && (
        <img
          src={`http://localhost:5000${post.image}`}
          alt="post"
          style={styles.image}
        />
      )}

      <div style={styles.actions}>
        <button style={{
          ...styles.likeBtn,
          color: liked ? '#e53e3e' : '#666'
        }} onClick={handleLike}>
          {liked ? '❤️' : '🤍'} {post.likes.length} Likes
        </button>
        <span style={styles.commentCount}>
          💬 {post.comments.length} Comments
        </span>
      </div>

      <div style={styles.comments}>
        {post.comments.map((c, i) => (
          <div key={i} style={styles.comment}>
            <strong>{c.username}: </strong>{c.text}
          </div>
        ))}
      </div>

      <form onSubmit={handleComment} style={styles.commentForm}>
        <input
          style={styles.commentInput}
          placeholder="Write a comment..."
          value={comment}
          onChange={e => setComment(e.target.value)}
        />
        <button style={styles.commentBtn} type="submit">Send</button>
      </form>
    </div>
  );
}

const styles = {
  card: { background: '#fff', padding: '1.5rem', borderRadius: '12px',
    boxShadow: '0 2px 8px rgba(0,0,0,0.08)', marginBottom: '1.5rem' },
  header: { display: 'flex', alignItems: 'center', gap: '12px', marginBottom: '1rem' },
  avatar: { fontSize: '32px' },
  username: { margin: 0, fontWeight: 'bold', color: '#1a1a2e' },
  time: { margin: 0, fontSize: '12px', color: '#999' },
  text: { fontSize: '15px', color: '#333', marginBottom: '1rem' },
  image: { width: '100%', borderRadius: '8px', marginBottom: '1rem' },
  actions: { display: 'flex', gap: '16px', marginBottom: '1rem' },
  likeBtn: { background: 'none', border: 'none',
    fontSize: '15px', cursor: 'pointer', fontWeight: 'bold' },
  commentCount: { fontSize: '15px', color: '#666' },
  comments: { marginBottom: '1rem' },
  comment: { fontSize: '14px', color: '#444',
    padding: '6px 0', borderBottom: '1px solid #f0f0f0' },
  commentForm: { display: 'flex', gap: '8px' },
  commentInput: { flex: 1, padding: '10px', borderRadius: '8px',
    border: '1px solid #ddd', fontSize: '14px' },
  commentBtn: { padding: '10px 16px', background: '#4f46e5',
    color: '#fff', border: 'none', borderRadius: '8px', cursor: 'pointer' },
};
